<?php
namespace App\Http\Controllers\Auth;
use App\Http\Controllers\Controller;use App\Models\{SecurityEvent,User};use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;
class LoginController extends Controller{
 public function create(){return view('auth.login');}
 public function store(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required|string']);$candidate=User::where('email',$data['email'])->first();if(!Auth::attempt($data,$r->boolean('remember'))){SecurityEvent::create(['property_id'=>$candidate?->property_id,'user_id'=>$candidate?->id,'event_type'=>'login_failed','severity'=>'warning','ip_address'=>$r->ip(),'user_agent'=>$r->userAgent(),'context'=>['email'=>$data['email']],'occurred_at'=>now()]);return back()->withErrors(['email'=>'The supplied credentials are incorrect.'])->onlyInput('email');}$r->session()->regenerate();if(!$r->user()->is_active){SecurityEvent::create(['property_id'=>$r->user()->property_id,'user_id'=>$r->user()->id,'event_type'=>'inactive_account_login','severity'=>'warning','ip_address'=>$r->ip(),'user_agent'=>$r->userAgent(),'occurred_at'=>now()]);Auth::logout();return back()->withErrors(['email'=>'This account is inactive.']);}SecurityEvent::create(['property_id'=>$r->user()->property_id,'user_id'=>$r->user()->id,'event_type'=>'login_success','severity'=>'info','ip_address'=>$r->ip(),'user_agent'=>$r->userAgent(),'occurred_at'=>now()]);return redirect()->intended(route('dashboard'));}
 public function destroy(Request $r){$u=$r->user();if($u)SecurityEvent::create(['property_id'=>$u->property_id,'user_id'=>$u->id,'event_type'=>'logout','severity'=>'info','ip_address'=>$r->ip(),'user_agent'=>$r->userAgent(),'occurred_at'=>now()]);Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('login');}
}
